  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Frequent hemodialysis versus standard hemodialysis for people with kidney failure: Systematic review and meta-analysis of randomized controlled trials.",
      "reason": "The title explicitly includes the phrase 'Systematic review', identifying the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Frequent hemodialysis versus standard hemodialysis for people with kidney failure: Systematic review and meta-analysis of randomized controlled trials.",
      "reason": "The title specifies the population ('people with kidney failure') and the interventions compared ('Frequent hemodialysis versus standard hemodialysis'), providing key information about the review question."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Frequent hemodialysis versus standard hemodialysis for people with kidney failure: Systematic review and meta-analysis of randomized controlled trials.",
      "reason": "The title includes supplementary information about the analysis method ('meta-analysis') and the included study design ('randomized controlled trials')."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Previous randomized and observational studies have shown that frequent dialysis, conducted more often than three times a week, provides more effective removal of fluid and uremic toxins, improves cardiovascular surrogates and quality of life, but the effect on survival in individual studies has remained uncertain [6, 7].",
      "reason": "The manuscript describes the current state of knowledge (benefits on surrogate outcomes) and explicitly notes important uncertainties (uncertain effect on survival)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Given the uncertain evidence for frequent hemodialysis (4 or more sessions per week), we conducted a systematic review to evaluate the benefits and harms of frequent hemodialysis compared with standard hemodialysis in people with kidney failure.",
      "reason": "The authors state the importance and need for the review, linking it to uncertainty in existing evidence and motivating the review objective."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_17",
      "quote": "For our knowledge this is the first systematic review assessing the efficacy and safety of frequent hemodialysis compared with standard hemodialysis for the treatment of kidney failure in RCTs only. A previous review that included both primary studies and systematic reviews evaluated the effects of frequent hemodialysis on surrogate outcomes, showing that frequent dialysis improved blood pressure management that may potentially lead to improvement in survival, cardiovascular outcomes, and quality of life, although no outcome data were reported to support these results [22].",
      "reason": "The manuscript identifies prior reviews, contrasts the current review with them (RCTs-only) and explains the need for this updated/focused review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Previous randomized and observational studies have shown that frequent dialysis, conducted more often than three times a week, provides more effective removal of fluid and uremic toxins, improves cardiovascular surrogates and quality of life...",
      "reason": "The authors briefly describe a plausible mechanism/mediators of effect (better removal of fluid and uremic toxins leading to improved cardiovascular surrogates and quality of life)."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model or figure showing hypothesised relationships between intervention components and outcomes is provided in the supplied evidence."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "We evaluated the benefits and harms of frequent hemodialysis in people with kidney failure compared with standard hemodialysis.",
      "reason": "The abstract contains an explicit statement of the review objective/question describing evaluation of benefits and harms of frequent versus standard hemodialysis."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_3; text_10",
      "quote": "We evaluated the benefits and harms of frequent hemodialysis in people with kidney failure compared with standard hemodialysis.\n\nThe primary review outcome was health-related quality of life (including physical or mental health). ... description of the intervention (type of hemodialysis, frequency, hours per session), and outcomes.",
      "reason": "The review clearly states the comparison (frequent hemodialysis versus standard hemodialysis) and describes interventions and outcomes, but it does not present the planned comparisons in a fully explicit PICO-structured format."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Randomized controlled trials were eligible whether they evaluated frequent hemodialysis for treatment of kidney failure in adults on hemodialysis for at least 3 months. Frequent hemodialysis was defined as any hemodialysis schedule occurring more than three times a week, regardless of the duration of each hemodialysis session. Standard hemodialysis was defined as three times a week. We included studies of any duration. Quasi-RCTs (such as those studies in which treatment allocation was performed by alternation, use of alternate medical records, or days of the week) were excluded. Crossover studies and cluster randomized controlled trials were eligible.",
      "reason": "The methods explicitly define population (adults on hemodialysis ≥3 months), interventions (frequent vs standard hemodialysis), eligible study designs (randomized trials, crossover, cluster RCTs; quasi-RCTs excluded), and duration criteria."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "A highly sensitive search strategy was conducted in MEDLINE, Embase and the Cochrane Central Register of Controlled Trials (CENTRAL), and the grey literature has been searched using Google Scholar from inception to 3 January 2024 without language restrictions (S1 File).",
      "reason": "The review specifies the search time frame (to 3 January 2024) and explicitly states there were no language restrictions and that grey literature was searched, addressing dissemination year and language/report searching considerations."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information was provided distinguishing exclusion of studies because outcomes were not measured from exclusion because outcome results were not reported; reasons for exclusions are cited as available in Covidence but no explicit distinction is described in the manuscript text provided."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Frequent hemodialysis was defined as any hemodialysis schedule occurring more than three times a week, regardless of the duration of each hemodialysis session. Standard hemodialysis was defined as three times a week.",
      "reason": "The review specifies the groups used in the comparisons/syntheses (frequent >3×/week versus standard 3×/week), directly linking the intervention and comparator groups used for synthesis."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not provide rationales for notable restrictions on study eligibility (for example, why quasi-RCTs were excluded or why adults on hemodialysis ≥3 months were required); no justification text is present in the provided evidence."
    }
  ],
  "confidence": 75
}

